  } satisfies ITodoListUser.IJoin;
  const userAuth: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: joinInput });
  typia.assert(userAuth);
  TestValidator.equals(
    "registered email matches input",
    userAuth.email,
    joinInput.email,
  );
  // Token set in connection.headers automatically

  // 2. Self-delete the account with authentication
  await api.functional.todoList.user.users.self.erase(connection);

  // 3. (No login endpoint provided, so cannot test re-login is impossible. If login endpoint were available, would test that login with the same credentials fails.)
  // 4. (No APIs to verify data removal, so cannot check todos, session data, or audit logs. Would check if available.)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Verifies /auth/user/refresh robustly rejects invalid, expired, or revoked
 * tokens without information leakage.
 *
 * Steps:
 *
 * 1. Register a legitimate new user and log in to get a real refresh token.
 * 2. Attempt refresh using a fabricated random token string.
 * 3. Attempt refresh with a structurally valid but unrelated token value.
 * 4. Attempt refresh using a valid token after simulating deletion (no delete API,
 *    so log in again for a new session).
 * 5. Attempt refresh using an old (but previously valid) token after login rotates
 *    it (token invalidation simulation).
 * 6. Verify for every case:
 *
 *    - The refresh fails (throws/rejects).
 *    - No new tokens are issued.
 *    - The error message does not reveal existence of the session, user, or reason.
 *    - The API behaviour is consistent and generic regardless of token or user
 *         state.
 */
export async function test_api_auth_refresh_with_invalid_or_expired_token(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const joinBody = {
    email: RandomGenerator.alphaNumeric(10) + "@example.com",
    password: RandomGenerator.alphaNumeric(12),
    href: "https://test.local/join",
    referrer: "https://test.local/landing",
  } satisfies ITodoListUser.IJoin;
  const user = await api.functional.auth.user.join(connection, {
    body: joinBody,
  });
  typia.assert(user);

  // 2. Log in to get real refresh token
  const loginBody = {
    email: joinBody.email,
    password: joinBody.password as string & tags.Format<"password">,
    href: "https://test.local/login",
    referrer: "https://test.local/landing",
  } satisfies ITodoListUser.ILogin;
  const loginRes = await api.functional.auth.user.login(connection, {
    body: loginBody,
  });
  typia.assert(loginRes);
  const validRefreshToken = loginRes.token.refresh;

  // 3. Use a random fabricated token
  const fakeToken = RandomGenerator.alphaNumeric(48);
  await TestValidator.error(
    "refresh should fail for a fabricated token",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: { refresh_token: fakeToken } satisfies ITodoListUser.IRefresh,
      });
    },
  );

  // 4. Use a structurally valid but unrelated token (UUID format)
  const uuidToken = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "refresh should fail for structurally valid but unrelated token",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: { refresh_token: uuidToken } satisfies ITodoListUser.IRefresh,
      });
    },
  );

  // 5. Use old refresh token after rotation (login again to rotate token)
  const loginRes2 = await api.functional.auth.user.login(connection, {
    body: loginBody,
  });
  typia.assert(loginRes2);
  const newRefreshToken = loginRes2.token.refresh;
  await TestValidator.error(
    "refresh should fail for old (rotated) token",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: validRefreshToken,
        } satisfies ITodoListUser.IRefresh,
      });
    },
  );

  // 6. Attempt refresh after invalidating session (simulate expired/invalid by reuse and randomness)
  await TestValidator.error(
    "refresh should fail for random token (expired simulation)",
    async () => {
      await api.functional.auth.user.refresh(connection, {
        body: {
          refresh_token: RandomGenerator.alphaNumeric(48),
        } satisfies ITodoListUser.IRefresh,
      });
    },
  );

  // 7. Attempt refresh with current valid token for completeness (should succeed)
  const validRefRes = await api.functional.auth.user.refresh(connection, {
    body: { refresh_token: newRefreshToken } satisfies ITodoListUser.IRefresh,
  });
  typia.assert(validRefRes);
  TestValidator.equals(
    "refresh issues a new access token for valid token",
    typeof validRefRes.token.access,
    "string",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validates that an authenticated user can retrieve their own profile
 * information using the /todoList/user/users/self endpoint. The scenario checks
 * proper end-to-end isolation and security of user profile retrieval. Steps:
 *
 * 1. Register a brand new user account for the purpose of the test, using a unique
 *    random email and password that meet schema constraints. Other audit fields
 *    (href, referrer) are filled with realistic URIs. Save the output for later
 *    checks.
 * 2. Log in with the newly registered user's credentials (email, password, and
 *    context fields). Obtain the JWT token and authorized user output.
 * 3. Immediately invoke the /todoList/user/users/self endpoint as the
 *    authenticated user, ensuring Bearer authorization (handled by SDK
 *    automatically).
 * 4. Validate that the self-profile response correctly matches the registered
 *    user: all fields (id, email, created_at, updated_at, and optional
 *    deleted_at) must be present and correct, with no sensitive or extraneous
 *    data. Assert that id, email, and timestamps in the response match those
 *    issued at registration/login.
 * 5. For extra isolation, ensure that no other user's data appears in this
 *    response.
 */
export async function test_api_user_self_profile_retrieval(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const joinInput = {
    email: typia.random<
      string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">
    >(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<255>>(),
    href: "https://e2e.test/join",
    referrer: "https://e2e.test/referrer",
  } satisfies ITodoListUser.IJoin;
  const joinResult = await api.functional.auth.user.join(connection, {
    body: joinInput,
  });
  typia.assert(joinResult);

  // 2. Log in as this user
  const loginInput = {
    email: joinInput.email,
    password: joinInput.password as string & tags.Format<"password">,
    href: "https://e2e.test/login",
    referrer: "https://e2e.test/login-referrer",
  } satisfies ITodoListUser.ILogin;
  const loginResult = await api.functional.auth.user.login(connection, {
    body: loginInput,
  });
  typia.assert(loginResult);

  // 3. Retrieve own profile
  const selfProfile =
    await api.functional.todoList.user.users.self.at(connection);
  typia.assert(selfProfile);

  // 4. Assert id, email, and timestamps match, and no sensitive data present
  TestValidator.equals(
    "self-profile id matches login",
    selfProfile.id,
    loginResult.id,
  );
  TestValidator.equals(
    "self-profile email matches login",
    selfProfile.email,
    loginResult.email,
  );
  TestValidator.equals(
    "self-profile created_at matches login",
    selfProfile.created_at,
    loginResult.created_at,
  );
  TestValidator.equals(
    "self-profile updated_at matches login",
    selfProfile.updated_at,
    loginResult.updated_at,
  );
  TestValidator.equals(
    "self-profile deleted_at matches login",
    selfProfile.deleted_at,
    loginResult.deleted_at,
  );

  // 5. Always validate that the self-profile output does not have token or password
  TestValidator.predicate(
    "self profile contains only allowed fields",
    Object.keys(selfProfile).every((k) =>
      ["id", "email", "created_at", "updated_at", "deleted_at"].includes(k),
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Verify that retrieving the authenticated user's profile without a proper
 * authentication token is forbidden.
 *
 * This test ensures that calling /todoList/user/users/self without an
 * Authorization header, or with invalid or unrelated tokens, is reliably
 * denied. No user profile information should be returned, and an authorization
 * error must be raised every time. The logic is as follows:
 *
 * 1. Create an unauthenticated connection by setting headers to an empty object.
 * 2. Attempt to call api.functional.todoList.user.users.self.at with the
 *    unauthenticated connection. It must throw an error.
 * 3. Generate a series of invalid, expired, or unrelated tokens (random fake JWTs)
 *    and call the endpoint with each as Authorization: Bearer <token>. Every
 *    request must result in an authorization error.
 * 4. No response should ever contain user profile data.
 */
export async function test_api_user_self_profile_retrieval_without_auth(
  connection: api.IConnection,
) {
  // 1. Create unauthenticated connection (no Authorization header)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  // 2. Attempt access with no headers
  await TestValidator.error(
    "Accessing /todoList/user/users/self without Authorization header must fail",
    async () => {
      await api.functional.todoList.user.users.self.at(unauthConn);
    },
  );

  // 3. Attempt access with invalid/malformed/expired/unrelated tokens
  const invalidTokens = [
    "not-a-jwt", // not JWT
    "Bearer this.is.not.a.valid.jwt.token",
    RandomGenerator.alphaNumeric(32),
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.invalid-signature.payload",
    "", // empty string
  ];
  for (const token of invalidTokens) {
    const connWithFakeToken: api.IConnection = {
      ...connection,
      headers: { Authorization: "Bearer " + token },
    };
    await TestValidator.error(
      `Access with invalid Authorization: Bearer ${token || "<empty>"} must fail`,
      async () => {
        await api.functional.todoList.user.users.self.at(connWithFakeToken);
      },
    );
  }
}

