import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Update a single field (title) on an existing todo and validate business,
 * audit, and security logic.
 *
 * 1. Register a new user for todo context (join)
 * 2. Create a todo for this user (POST)
 * 3. Update the todo's title using the update API, only sending the title field
 * 4. Validate:
 *
 *    - Title is updated, other fields unchanged
 *    - Updated_at is different/newer
 *    - User can only update own todos (positive and negative ownership)
 *    - Title length and blank rules enforced (runtime/business constraint
 *         validation)
 * 5. Negative case: forbidden update as another user and rejected invalid title
 */
export async function test_api_todo_update_single_field(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const email: string = typia.random<string & tags.Format<"email">>();
  const joinHref: string = "https://example.com/join";
  const joinReferrer: string = "https://google.com/";
  const user: ITodoListUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email,
        password: RandomGenerator.alphaNumeric(12),
        href: joinHref,
        referrer: joinReferrer,
      } satisfies ITodoListUser.IJoin,
    },
  );
  typia.assert(user);

  // 2. Create a new todo
  const origTitle = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 4,
    wordMax: 12,
  }).slice(0, 80);
  const origDescription = RandomGenerator.paragraph({ sentences: 3 });
  const origDueDate = new Date(Date.now() + 86400000).toISOString(); // tomorrow
  const todo: ITodoListTodo = await api.functional.todoList.user.todos.create(
    connection,
    {
      body: {
        title: origTitle,
        description: origDescription,
        due_date: origDueDate,
      } satisfies ITodoListTodo.ICreate,
    },
  );
  typia.assert(todo);
  TestValidator.equals("created title", todo.title, origTitle);
  TestValidator.equals(
    "created description",
    todo.description,
    origDescription,
  );
  TestValidator.equals("created due_date", todo.due_date, origDueDate);
  TestValidator.equals("created completed", todo.completed, false);

  // 3. Update the title of the todo (nothing else)
  const newTitle = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 10,
    wordMax: 20,
  }).slice(0, 95);
  await new Promise((r) => setTimeout(r, 5)); // ensure timestamp gap
  const updated: ITodoListTodo =
    await api.functional.todoList.user.todos.update(connection, {
      todoId: todo.id,
      body: {
        title: newTitle,
      } satisfies ITodoListTodo.IUpdate,
    });
  typia.assert(updated);
  TestValidator.equals("title updated", updated.title, newTitle);
  TestValidator.equals(
    "description unchanged",
    updated.description,
    todo.description,
  );
  TestValidator.equals("due date unchanged", updated.due_date, todo.due_date);
  TestValidator.equals(
    "completed unchanged",
    updated.completed,
    todo.completed,
  );
  TestValidator.equals("id unchanged", updated.id, todo.id);
  TestValidator.notEquals(
    "updated_at is modified",
    updated.updated_at,
    todo.updated_at,
  );

  // 4. Try to update with invalid title: blank title
  await TestValidator.error("blank title should be rejected", async () => {
    await api.functional.todoList.user.todos.update(connection, {
      todoId: todo.id,
      body: {
        title: "", // invalid: blank
      } satisfies ITodoListTodo.IUpdate,
    });
  });
  // 4(b). Try to update with invalid title: too long
  await TestValidator.error("too long title should be rejected", async () => {
    await api.functional.todoList.user.todos.update(connection, {
      todoId: todo.id,
      body: {
        title: RandomGenerator.alphaNumeric(101), // invalid: exceeds 100 chars
      } satisfies ITodoListTodo.IUpdate,
    });
  });

  // 5. Negative case: register a second user and attempt to update other's todo
  const anotherEmail: string = typia.random<string & tags.Format<"email">>();
  const anotherUser: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: {
        email: anotherEmail,
        password: RandomGenerator.alphaNumeric(12),
        href: joinHref,
        referrer: joinReferrer,
      } satisfies ITodoListUser.IJoin,
    });
  typia.assert(anotherUser);
  // Auth context: the SDK should automatically use the token of the most recently joined user
  await TestValidator.error(
    "other user forbidden from updating todo",
    async () => {
      await api.functional.todoList.user.todos.update(connection, {
        todoId: todo.id,
        body: {
          title: RandomGenerator.paragraph({ sentences: 1 }),
        } satisfies ITodoListTodo.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validates updating all editable fields of a todo item at once for the
 * authenticated user.
 *
 * 1. Register a new user for authentication context.
 * 2. Create a todo item owned by that user.
 * 3. Update all editable fields for that todo (title, description, completed,
 *    due_date), including setting description and due_date to null.
 * 4. Check updated fields, null removals, and updated_at timestamp increased.
 * 5. Attempt forbidden update as different user.
 */
export async function test_api_todo_update_multiple_fields(
  connection: api.IConnection,
) {
  // 1. Register a new user
  const registerBody = {
    email: typia.random<
      string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">
    >(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://test.domain/register",
    referrer: "https://test.domain/landing",
  } satisfies ITodoListUser.IJoin;
  const authUser: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: registerBody });
  typia.assert(authUser);

  // 2. Create a todo for the new user
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 2, wordMax: 15 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
    due_date: new Date(Date.now() + 864e5).toISOString(),
  } satisfies ITodoListTodo.ICreate;
  const todo: ITodoListTodo = await api.functional.todoList.user.todos.create(
    connection,
    { body: createBody },
  );
  typia.assert(todo);

  // 3. Update all editable fields (title, description, completed, due_date), remove optional properties by setting null
  const updateBody = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 2, wordMax: 20 }),
    description: null,
    completed: true,
    due_date: null,
  } satisfies ITodoListTodo.IUpdate;
  const updated: ITodoListTodo =
    await api.functional.todoList.user.todos.update(connection, {
      todoId: todo.id,
      body: updateBody,
    });
  typia.assert(updated);

  // 4. Confirm all changes; ensure nulls are reflected and updated_at is increased
  TestValidator.equals("updated todo id", updated.id, todo.id);
  TestValidator.equals(
    "updated title matches",
    updated.title,
    updateBody.title,
  );
  TestValidator.equals("description removed", updated.description, null);
  TestValidator.equals("completed field set", updated.completed, true);
  TestValidator.equals("due_date removed", updated.due_date, null);
  TestValidator.predicate(
    "updated_at advanced",
    new Date(updated.updated_at).getTime() >
      new Date(todo.updated_at).getTime(),
  );

  // 5. Register a second user to verify unauthorized update is forbidden
  const regBody2 = {
    email: typia.random<
      string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">
    >(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://test.domain/register",
    referrer: "https://test.domain/landing",
  } satisfies ITodoListUser.IJoin;
  const otherUser: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: regBody2 });
  typia.assert(otherUser);

  // Try to update as a different authenticated user (should fail)
  await TestValidator.error("other user cannot update todo", async () => {
    await api.functional.todoList.user.todos.update(connection, {
      todoId: todo.id,
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
      } satisfies ITodoListTodo.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate deletion of a todo item by its owner.
 *
 * This test ensures that after registering a user and creating a todo item, the
 * user can successfully delete the todo by its ID. It confirms that deleted
 * todos are fully removed, cannot be deleted again, and all actions respect
 * authentication context and data integrity. Error case: attempting to delete
 * the same todo twice should fail with not-found behavior. Ownership is
 * strictly enforced. Steps:
 *
 * 1. Register a user
 * 2. Create a todo item as the user
 * 3. Delete the todo by ID (expect success)
 * 4. Attempt to delete the same todo again (expect error)
 */
export async function test_api_todo_delete_by_owner(
  connection: api.IConnection,
) {
  // 1. Register the user
  const userJoinBody = {
    email: typia.random<
      string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">
    >(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://test.todo/e2e/join",
    referrer: "https://test.todo/e2e/source",
  } satisfies ITodoListUser.IJoin;
  const userAuth: ITodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: userJoinBody });
  typia.assert(userAuth);

  // 2. Create a todo item as this user
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 2, wordMax: 5 }),
    description: RandomGenerator.paragraph({
      sentences: 8,
      wordMin: 3,
      wordMax: 10,
    }),
    due_date: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
  } satisfies ITodoListTodo.ICreate;
  const todo: ITodoListTodo = await api.functional.todoList.user.todos.create(
    connection,
    { body: todoCreateBody },
  );
  typia.assert(todo);
  TestValidator.equals(
    "todo is owned by user",
    todo.todo_list_user_id,
    userAuth.id,
  );
  TestValidator.equals(
    "todo title matches input",
    todo.title,
    todoCreateBody.title,
  );
  if (
    todoCreateBody.description !== null &&
    todoCreateBody.description !== undefined
  ) {
    TestValidator.equals(
      "todo description matches input",
      todo.description,
      todoCreateBody.description,
    );
  }
  if (
    todoCreateBody.due_date !== null &&
    todoCreateBody.due_date !== undefined
  ) {
    TestValidator.equals(
      "todo due date matches input",
      todo.due_date,
      todoCreateBody.due_date,
    );
  }

  // 3. Delete the todo by its ID (success case)
  await api.functional.todoList.user.todos.erase(connection, {
    todoId: todo.id,
  });

  // 4. Attempt to delete the same todo again (error case: not found)
  await TestValidator.error(
    "repeated deletion of already-removed todo should fail",
    async () => {
      await api.functional.todoList.user.todos.erase(connection, {
        todoId: todo.id,
      });
    },
  );
}

